x = (2*rand(1,200)-1).*sqrt(pi/2);
y = (2*rand(1,200)-1).*sqrt(pi/2);
[X,Y] = meshgrid(x,y);
Z = sin(X.^2 + Y.^2);

figure; %[output:0edb14f8]
surf(X,Y,Z); %[output:0edb14f8]
colormap(cool); %[output:0edb14f8]
shading interp; %[output:0edb14f8]
view(50,50); %[output:0edb14f8]

xlabel('x'); %[output:0edb14f8]
ylabel('y'); %[output:0edb14f8]
zlabel('f(x,y)'); %[output:0edb14f8]
title('f(x,y) = sin(x^2 + y^2)'); %[output:0edb14f8]
grid on; %[output:0edb14f8]
axis tight; %[output:0edb14f8]
%%
x = linspace(-2,1,200);
y = linspace(-2,1,200);
[X,Y] = meshgrid(x,y);
Z = 1 - 2*X.^2 - 3*Y.^2;

figure; %[output:82185f06]
surf(X,Y,Z); %[output:82185f06]
colormap(parula); %[output:82185f06]
shading interp; %[output:82185f06]
view(60,60); %[output:82185f06]

xlabel('x'); %[output:82185f06]
ylabel('y'); %[output:82185f06]
zlabel('f(x,y)'); %[output:82185f06]
title('f(x,y) = 1 - 2x^2 - 3y^2'); %[output:82185f06]
grid on; %[output:82185f06]
axis tight; %[output:82185f06]
%%
x = linspace(-2,2,150);
y = linspace(-2,2,150);
[X,Y] = meshgrid(x,y);
Z = 1 - (X.^2 + Y.^2);
figure; %[output:9c201116]

subplot(3,1,1); %[output:9c201116]

surf(X,Y,Z); %[output:9c201116]
shading interp; %[output:9c201116]
colormap(gca, parula); %[output:9c201116]

xlabel('x'); %[output:9c201116]
ylabel('y'); %[output:9c201116]
zlabel('z'); %[output:9c201116]
title('Parula'); %[output:9c201116]
grid on; %[output:9c201116]
view(45,30); %[output:9c201116]

subplot(3,1,2); %[output:9c201116]

surf(X,Y,Z); %[output:9c201116]
shading interp; %[output:9c201116]
colormap(gca, cool); %[output:9c201116]

xlabel('x'); %[output:9c201116]
ylabel('y'); %[output:9c201116]
zlabel('z'); %[output:9c201116]
title('Cool'); %[output:9c201116]
grid on; %[output:9c201116]
view(45,30); %[output:9c201116]

subplot(3,1,3); %[output:9c201116]

surf(X,Y,Z); %[output:9c201116]
shading interp; %[output:9c201116]
colormap(gca, jet); %[output:9c201116]

xlabel('x'); %[output:9c201116]
ylabel('y'); %[output:9c201116]
zlabel('z'); %[output:9c201116]
title('Jet'); %[output:9c201116]
grid on; %[output:9c201116]
view(45,30); %[output:9c201116]

